-- 1. Total revenue generated by male vs female customers
SELECT GENDER,
       SUM(PURCHASE_AMOUNT) AS TOTAL_REVENUE
FROM CUSTOMER
GROUP BY GENDER
ORDER BY TOTAL_REVENUE DESC;


-- 2. Customers who used a discount but spent more than
--    the average purchase amount
SELECT CUSTOMER_ID,
       PURCHASE_AMOUNT
FROM CUSTOMER
WHERE DISCOUNT_APPLIED = 'Yes'
  AND PURCHASE_AMOUNT > (
      SELECT AVG(PURCHASE_AMOUNT)
      FROM CUSTOMER
  )
ORDER BY PURCHASE_AMOUNT DESC;


-- Q3. Top 5 products with highest average review rating
SELECT ITEM_PURCHASED,
       AVG(REVIEW_RATING) AS AVG_REVIEW_RATING
FROM CUSTOMER
GROUP BY ITEM_PURCHASED
ORDER BY AVG(REVIEW_RATING) DESC
FETCH FIRST 5 ROWS ONLY;


-- Q4. Average purchase amount by shipping type
SELECT SHIPPING_TYPE,
       AVG(PURCHASE_AMOUNT) AS AVG_PURCHASE_AMOUNT
FROM CUSTOMER
WHERE SHIPPING_TYPE IN ('Standard', 'Express')
GROUP BY SHIPPING_TYPE
ORDER BY AVG_PURCHASE_AMOUNT DESC;


-- Q5. Subscribers vs non-subscribers
SELECT SUBSCRIPTION_STATUS,
       AVG(PURCHASE_AMOUNT) AS AVG_SPEND,
       SUM(PURCHASE_AMOUNT) AS TOTAL_REVENUE
FROM CUSTOMER
GROUP BY SUBSCRIPTION_STATUS
ORDER BY SUBSCRIPTION_STATUS;


-- Q6. Top 5 products by discount percentage
SELECT  ITEM_PURCHASED, ROUND(100 * SUM(CASE WHEN DISCOUNT_APPLIED = 'Yes' THEN 1 ELSE 0 END ) / COUNT(*), 2) AS DISCOUNT_PERCENTAGE
FROM CUSTOMER
GROUP BY  ITEM_PURCHASED
ORDER BY DISCOUNT_PERCENTAGE DESC
FETCH FIRST 5 ROWS ONLY;


-- Q7. Customer segmentation
SELECT
    CASE
        WHEN PREVIOUS_PURCHASES <= 1 THEN 'New'
        WHEN PREVIOUS_PURCHASES <= 5 THEN 'Returning'
        ELSE 'Loyal'
    END AS CUSTOMER_SEGMENT,
    COUNT(*) AS CUSTOMER_COUNT
FROM CUSTOMER
GROUP BY
    CASE
        WHEN PREVIOUS_PURCHASES <= 1 THEN 'New'
        WHEN PREVIOUS_PURCHASES <= 5 THEN 'Returning'
        ELSE 'Loyal'
    END
ORDER BY CUSTOMER_COUNT DESC;


-- Q8. Top 3 products within each category
SELECT CATEGORY,
        ITEM_PURCHASED,
       PURCHASE_COUNT
FROM (
    SELECT CATEGORY,
            ITEM_PURCHASED,
           COUNT(*) AS PURCHASE_COUNT,
           ROW_NUMBER() OVER (
               PARTITION BY CATEGORY
               ORDER BY COUNT(*) DESC
           ) AS RN
    FROM CUSTOMER
    GROUP BY CATEGORY,  ITEM_PURCHASED
)
WHERE RN <= 3
ORDER BY CATEGORY, PURCHASE_COUNT DESC;


-- Q9. Repeat buyers and subscription status
SELECT SUBSCRIPTION_STATUS,
       COUNT(*) AS REPEAT_BUYER_COUNT,
       ROUND(
           100 * COUNT(*) / SUM(COUNT(*)) OVER (),
           2
       ) AS PERCENTAGE
FROM CUSTOMER
WHERE PREVIOUS_PURCHASES > 5
GROUP BY SUBSCRIPTION_STATUS
ORDER BY PERCENTAGE DESC;


-- Q10. Revenue contribution by age group
SELECT AGE_GROUP,
       SUM(PURCHASE_AMOUNT) AS TOTAL_REVENUE,
       ROUND(
           100 * SUM(PURCHASE_AMOUNT) /
           (SELECT SUM(PURCHASE_AMOUNT) FROM CUSTOMER),
           2
       ) AS REVENUE_PERCENTAGE
FROM CUSTOMER
GROUP BY AGE_GROUP
ORDER BY TOTAL_REVENUE DESC;